<template>
  <div class="docnet-mission-list">
    <!-- Toolbar -->
    <div class="row items-center q-gutter-sm q-mb-md">
      <q-input
        v-model="searchQuery"
        :placeholder="$t('search')"
        outlined
        dense
        clearable
        style="min-width: 250px; max-width: 400px;"
        @update:model-value="onSearchInput"
      >
        <template #prepend>
          <q-icon name="search" size="xs" />
        </template>
      </q-input>
      <q-select
        v-model="sourceFilter"
        :options="sourceOptions"
        outlined
        dense
        emit-value
        map-options
        style="min-width: 160px;"
        @update:model-value="onSourceFilterChange"
      />
      <div class="mission-filters">
        <q-btn-toggle
          :model-value="statusFilter"
          no-caps
          rounded
          unelevated
          toggle-color="primary"
          color="white"
          text-color="primary"
          :options="filterOptions"
          class="mission-filter-toggle"
          @update:model-value="onStatusFilterChange"
        />
      </div>
      <q-space />
      <q-btn
        color="primary"
        icon="add"
        :label="$t('new_mission')"
        no-caps
        unelevated
        rounded
        @click="$router.push('/doc-net/mission-control')"
      />
    </div>

    <!-- Loading -->
    <div v-if="loading" class="text-center q-pa-xl">
      <q-spinner-dots color="primary" size="40px" />
    </div>

    <!-- Empty -->
    <div v-else-if="filteredMissions.length === 0" class="text-center q-pa-xl">
      <q-icon name="rocket_launch" size="64px" color="grey-5" />
      <p class="q-mt-md text-grey-6">
        {{ statusFilter === 'all' ? $t('no_missions_yet') : $t('docnet_no_status_missions', { status: statusFilterLabel }) }}
      </p>
    </div>

    <!-- Hierarchical mission list with sticky pagination -->
    <div v-else class="mission-list-container">
      <div class="mission-tree">
        <MissionTreeItem
          v-for="mission in rootMissions"
          :key="mission.id"
          :mission="mission"
          :children-map="childrenMap"
          :all-missions="filteredMissions"
          :depth="0"
          :progress-fn="missionStore.getMissionProgress"
          @select="onSelectMission"
          @edit="openEditDialog"
          @timeline="openTimeline"
          @restart="openRestartDialog"
          @delete="openDeleteDialog"
        />
      </div>

      <!-- Server-side pagination (matches DocBitsTable style) -->
      <div
        v-if="missionStore.totalMissions > 0"
        class="pagination-container flex justify-end"
      >
        <div class="row items-center">
          <div class="docbits-pagination-total q-mr-md">
            {{ missionStore.totalMissions }} {{ $t('total') }}
          </div>
          <PaginationSettings
            label="records_per_page"
            settings-key="docnet_missions_page_size"
            :options="['10', '20', '50']"
            :model-value="String(missionStore.pageSize)"
            @update:model-value="onPageSizeChange"
          />
          <q-separator vertical class="q-mx-md" />
          <q-pagination
            :model-value="missionStore.page"
            color="primary"
            :max="totalPages"
            class="q-py-xs"
            :max-pages="6"
            input
            boundary-links
            gutter="none"
            @update:model-value="onPageChange"
          />
        </div>
      </div>
    </div>

    <!-- Delete Confirmation Dialog -->
    <q-dialog v-model="showDeleteDialog">
      <q-card style="min-width: 350px">
        <q-card-section class="row items-center">
          <q-icon name="warning" color="negative" size="md" class="q-mr-sm" />
          <div class="text-h6">{{ $t('delete_mission') }}</div>
        </q-card-section>
        <q-separator />
        <q-card-section>
          <div class="row items-center no-wrap q-gutter-xs q-mb-sm">
            <q-badge
              v-if="namePrefix(deleteTarget)"
              color="blue-grey-3"
              text-color="blue-grey-9"
              :label="namePrefix(deleteTarget)"
            />
            <span class="text-weight-medium">{{ nameDisplay(deleteTarget) }}</span>
          </div>
          {{ $t('confirm_delete_mission') }}
        </q-card-section>
        <q-card-actions align="right">
          <q-btn flat :label="$t('cancel')" v-close-popup />
          <q-btn color="negative" :label="$t('delete')" :loading="deleting" @click="onDeleteMission" />
        </q-card-actions>
      </q-card>
    </q-dialog>

    <!-- Restart Confirmation Dialog -->
    <q-dialog v-model="showRestartDialog">
      <q-card style="min-width: 350px">
        <q-card-section class="row items-center">
          <q-icon name="restart_alt" color="primary" size="md" class="q-mr-sm" />
          <span class="text-h6">{{ $t('restart_mission') }}</span>
        </q-card-section>
        <q-separator />
        <q-card-section>
          <div class="row items-center no-wrap q-gutter-xs q-mb-sm">
            <q-badge
              v-if="namePrefix(restartTarget)"
              color="blue-grey-3"
              text-color="blue-grey-9"
              :label="namePrefix(restartTarget)"
            />
            <span class="text-weight-medium">{{ nameDisplay(restartTarget) }}</span>
          </div>
          {{ $t('restart_mission_confirm') }}
        </q-card-section>
        <q-card-actions align="right">
          <q-btn flat :label="$t('cancel')" v-close-popup />
          <q-btn color="primary" :label="$t('restart')" :loading="restarting" @click="onRestartMission" />
        </q-card-actions>
      </q-card>
    </q-dialog>

    <!-- Edit Mission Dialog -->
    <q-dialog v-model="showEditDialog">
      <q-card style="min-width: 400px">
        <q-card-section>
          <div class="text-h6">{{ $t('edit_mission') }}</div>
        </q-card-section>
        <q-card-section class="q-pt-none">
          <q-input
            v-model="editNameValue"
            :placeholder="$t('mission_name')"
            outlined
            dense
            autofocus
            class="edit-mission-input"
            @keyup.enter="saveEditName"
          />
        </q-card-section>
        <q-card-actions align="right">
          <q-btn flat :label="$t('cancel')" @click="showEditDialog = false" />
          <q-btn flat :label="$t('save')" color="primary" :disable="!editNameValue.trim()" @click="saveEditName" />
        </q-card-actions>
      </q-card>
    </q-dialog>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent } from 'vue';
import { debounce } from 'quasar';

import { useDocNetMissionStore } from 'src/store/DocNet/docnet-missions.store';
import { useDocNetIssueStore } from 'src/store/DocNet/docnet-issues.store';
import { storeToRefs } from 'pinia';
import type { DocNetMission } from 'src/@types/docnet';
import { formatMissionSource } from 'src/utils/docnet/formatting';
import MissionTreeItem from './components/MissionTreeItem.vue';
import PaginationSettings from 'src/components/Table/PaginationSettings.vue';

export default defineComponent({
  name: 'DocNetMissionList',

  components: {
    MissionTreeItem,
    PaginationSettings,
  },

  setup() {
    const missionStore = useDocNetMissionStore();
    const taskStore = useDocNetIssueStore();
    const { missions, loading } = storeToRefs(missionStore);
    return { missionStore, taskStore, missions, loading };
  },

  data() {
    const missionStore = useDocNetMissionStore();
    return {
      // All three filters are server-side — mirrored from store for v-model
      // binding. Search input text is local (so typing stays responsive and
      // the debounce doesn't cause cursor jumps), then pushed into the store
      // via setSearchFilter on each debounced tick.
      searchQuery: missionStore.searchFilter,
      sourceFilter: missionStore.sourceFilter || 'all',
      debouncedPushSearch: null as null | ((v: string) => void),
      showDeleteDialog: false,
      deleteTarget: null as DocNetMission | null,
      deleting: false,
      showRestartDialog: false,
      restartTarget: null as DocNetMission | null,
      restarting: false,
      showEditDialog: false,
      editTarget: null as DocNetMission | null,
      editNameValue: '',
    };
  },

  computed: {
    totalPages(): number {
      return Math.max(1, Math.ceil(this.missionStore.totalMissions / this.missionStore.pageSize));
    },

    /** Current status filter — '' means "all", read from store for server-side filtering */
    statusFilter(): string {
      return this.missionStore.statusFilter || 'all';
    },

    filterOptions() {
      return [
        { label: this.$t('docnet_all'), value: 'all' },
        { label: this.$t('docnet_active'), value: 'active' },
        { label: this.$t('docnet_planning'), value: 'planning' },
        { label: this.$t('docnet_waiting_approval'), value: 'waiting_approval' },
        { label: this.$t('docnet_completed'), value: 'completed' },
        { label: this.$t('docnet_cancelled'), value: 'cancelled' },
      ];
    },

    statusFilterLabel() {
      const match = this.filterOptions.find((o) => o.value === this.statusFilter);
      return match ? match.label : this.statusFilter;
    },

    sourceOptions() {
      // Intentionally no "Manual" entry: the backend's 'manual' value is
      // a server-side fallback for rows a writer forgot to tag, not a
      // product-level origin. Exposing it as a filter would let users
      // query for "things the system failed to classify" which isn't a
      // useful user workflow.
      //
      // Labels go through ``formatMissionSource`` so they pick up the
      // active locale (``source_<token>`` keys) for translatable
      // entries (Email, Mission Control, Agent) and stay hardcoded
      // for brand names (Discord, Slack, Teams) — same convention
      // used everywhere else this label is rendered.
      const $t = (k: string) => this.$t(k);
      const allLabel = (() => {
        const k = 'source_all';
        const t = $t(k);
        return t && t !== k ? t : 'All Sources';
      })();
      return [
        { label: allLabel, value: 'all' },
        { label: formatMissionSource({ source: 'mission_control' }, $t), value: 'mission_control' },
        { label: formatMissionSource({ source: 'email' }, $t), value: 'email' },
        { label: formatMissionSource({ source: 'discord' }, $t), value: 'discord' },
        { label: formatMissionSource({ source: 'slack' }, $t), value: 'slack' },
        { label: formatMissionSource({ source: 'teams' }, $t), value: 'teams' },
      ];
    },

    filteredMissions(): DocNetMission[] {
      // All three filters (status, source, search) are applied server-side —
      // see mission store's setStatusFilter/setSourceFilter/setSearchFilter.
      // This page therefore just renders the current server page as-is; no
      // additional client-side filtering is applied, which used to cause
      // "match exists but is on page 3" bugs.
      return this.missions as DocNetMission[];
    },

    /** Map parent_mission_id → children */
    childrenMap(): Record<string, DocNetMission[]> {
      const map: Record<string, DocNetMission[]> = {};
      for (const m of this.filteredMissions) {
        if (m.parent_mission_id) {
          if (!map[m.parent_mission_id]) map[m.parent_mission_id] = [];
          map[m.parent_mission_id].push(m);
        }
      }
      return map;
    },

    /** Top-level missions (no parent) */
    rootMissions(): DocNetMission[] {
      const childIds = new Set<string>();
      for (const m of this.filteredMissions) {
        if (m.parent_mission_id) childIds.add(m.id);
      }
      return this.filteredMissions.filter((m) => !childIds.has(m.id) || !m.parent_mission_id);
    },
  },

  methods: {
    /** Human-readable source label shown as a badge (e.g. "Email").
     *  Pass ``$t`` so the badge follows the active locale; falls
     *  back to the hardcoded English label when the
     *  ``source_<token>`` key isn't translated yet. */
    namePrefix(mission: DocNetMission | null | undefined): string {
      return formatMissionSource(mission, (k: string) => this.$t(k));
    },

    /** Mission name as-is. Legacy "[Prefix]" was stripped from every
     * row in the DOCB-9880 data migration, so ``mission.name`` is
     * already the clean display name.
     */
    nameDisplay(mission: DocNetMission | null | undefined): string {
      return mission?.name ?? '';
    },

    onSelectMission(mission: DocNetMission) {
      this.$router.push('/doc-net/missions/' + mission.id);
    },

    /** Jump straight to a mission's timeline from the row-level
     *  kebab — same destination the mission detail page's kebab
     *  exposes, so both menus stay in sync.  Timeline is debug
     *  surface; offering it from the list saves a navigation hop
     *  for power users investigating multiple missions. */
    openTimeline(mission: DocNetMission) {
      this.$router.push('/doc-net/missions/' + mission.id + '/timeline');
    },

    async onPageChange(page: number) {
      await this.missionStore.setMissionPage(page);
    },

    async onStatusFilterChange(value: string) {
      // 'all' means no server filter — pass empty string to clear
      await this.missionStore.setStatusFilter(value === 'all' ? '' : value);
    },

    onSearchInput(value: string | number | null) {
      // Keep the input model in sync for cursor stability, but defer the
      // server call through the 300ms debounce set up in mounted().
      const text = value == null ? '' : String(value);
      this.searchQuery = text;
      this.debouncedPushSearch?.(text);
    },

    async onSourceFilterChange(value: string) {
      await this.missionStore.setSourceFilter(value);
    },

    async onPageSizeChange(size: string) {
      this.missionStore.pageSize = Number(size);
      await this.missionStore.setMissionPage(1);
    },

    openDeleteDialog(mission: DocNetMission) {
      this.deleteTarget = mission;
      this.showDeleteDialog = true;
    },

    async onDeleteMission() {
      if (!this.deleteTarget) return;
      this.deleting = true;
      try {
        await this.missionStore.deleteMission(this.deleteTarget.id);
        this.showDeleteDialog = false;
        this.deleteTarget = null;
        notify.success(this.$t('docnet_mission_deleted'));
      } catch (error) {
        console.error('Failed to delete mission:', error);
        notify.error(this.$t('docnet_mission_delete_failed'));
      } finally {
        this.deleting = false;
      }
    },

    openEditDialog(mission: DocNetMission) {
      this.editTarget = mission;
      this.editNameValue = mission.name;
      this.showEditDialog = true;
    },

    async saveEditName() {
      if (!this.editTarget || !this.editNameValue.trim()) return;
      try {
        await this.missionStore.updateMission(this.editTarget.id, { name: this.editNameValue.trim() });
        this.showEditDialog = false;
        this.editTarget = null;
        notify.success(this.$t('docnet_mission_updated'));
      } catch (error) {
        console.error('Failed to update mission:', error);
        notify.error(this.$t('docnet_mission_update_failed'));
      }
    },

    openRestartDialog(mission: DocNetMission) {
      this.restartTarget = mission;
      this.showRestartDialog = true;
    },

    async onRestartMission() {
      if (!this.restartTarget) return;
      this.restarting = true;
      try {
        await this.missionStore.restartMission(this.restartTarget.id);
        this.showRestartDialog = false;
        this.restartTarget = null;
        notify.success(this.$t('docnet_mission_restarted'));
      } catch (error) {
        console.error('Failed to restart mission:', error);
        notify.error(this.$t('docnet_mission_restart_failed'));
      } finally {
        this.restarting = false;
      }
    },
  },

  async mounted() {
    // 300ms keeps the feel snappy without hammering the API on every keystroke
    // — matches the debounce cadence used by the /dashboard search.
    this.debouncedPushSearch = debounce((value: string) => {
      this.missionStore.setSearchFilter(value || '');
    }, 300);

    await Promise.all([
      this.missionStore.fetchMissions(),
      this.taskStore.fetchIssues(),
    ]);
  },

  beforeUnmount() {
    // Clear the persisted search via the setter so page resets to 1 too —
    // direct mutation would leave a stale page cursor for re-entry. Mirrors
    // the cleanup pattern in DocNetIssueList / DocNetEmail.
    if (this.missionStore.searchFilter) {
      void this.missionStore.setSearchFilter('');
    }
  },
});
</script>

