<template>
  <div class="mission-tree-item" :class="{ 'mission-tree-item--root': depth === 0 }">
    <!-- Mission row -->
    <div
      class="mission-row"
      :style="{ paddingLeft: (depth * 16 + 8) + 'px' }"
      @click="$emit('select', mission)"
    >
      <!-- Expand toggle -->
      <q-btn
        v-if="hasChildren || missionIssues.length > 0"
        flat
        dense
        round
        size="xs"
        :icon="expanded ? 'expand_more' : 'chevron_right'"
        class="expand-btn"
        @click.stop="expanded = !expanded"
      />
      <div v-else class="expand-placeholder" />

      <!-- Mission name + description -->
      <div class="mission-info">
        <div class="row items-center no-wrap q-gutter-xs">
          <q-badge v-if="namePrefix" color="blue-grey-3" text-color="blue-grey-9" :label="namePrefix" />
          <span class="mission-name">{{ displayName }}</span>
        </div>
        <span v-if="mission.description && !isEmailMission" class="mission-desc">{{ mission.description }}</span>
      </div>

      <!-- Spacer -->
      <q-space />

      <!-- Task count -->
      <span v-if="missionIssues.length > 0" class="mission-meta">
        <q-icon name="task_alt" size="14px" />
        {{ missionIssues.length }}
      </span>

      <!-- Sub-mission count -->
      <span v-if="hasChildren" class="mission-meta">
        <q-icon name="account_tree" size="14px" />
        {{ children.length }}
      </span>

      <!-- Orchestrator chip -->
      <AssigneeChip
        v-if="orchestratorName"
        :name="orchestratorName"
        type="agent"
        size="sm"
        class="q-mr-xs"
      />

      <!-- Status badge -->
      <StatusBadge :status="mission.status" size="sm" />

      <!-- Actions menu -->
      <q-btn
        flat
        round
        dense
        icon="more_vert"
        size="sm"
        class="actions-btn"
        @click.stop
      >
        <q-menu>
          <q-list dense>
            <q-item clickable v-close-popup @click.stop="$emit('edit', mission)">
              <q-item-section avatar><q-icon name="edit" size="xs" /></q-item-section>
              <q-item-section>{{ $t('edit_mission') || 'Edit mission' }}</q-item-section>
            </q-item>
            <q-item clickable v-close-popup @click.stop="$emit('timeline', mission)">
              <q-item-section avatar><q-icon name="history" size="xs" /></q-item-section>
              <q-item-section>{{ $t('timeline') }}</q-item-section>
            </q-item>
            <q-item clickable v-close-popup @click.stop="$emit('restart', mission)">
              <q-item-section avatar><q-icon name="restart_alt" size="xs" /></q-item-section>
              <q-item-section>{{ $t('restart_mission') || 'Restart mission' }}</q-item-section>
            </q-item>
            <q-item clickable v-close-popup @click.stop="$emit('delete', mission)" class="text-negative">
              <q-item-section avatar><q-icon name="delete" size="xs" /></q-item-section>
              <q-item-section>{{ $t('delete_mission') || 'Delete mission' }}</q-item-section>
            </q-item>
          </q-list>
        </q-menu>
      </q-btn>
    </div>

    <!-- Children (expanded) -->
    <div v-if="expanded && hasChildren" class="mission-children">
      <MissionTreeItem
        v-for="child in children"
        :key="child.id"
        :mission="child"
        :children-map="childrenMap"
        :all-missions="allMissions"
        :depth="depth + 1"
        :progress-fn="progressFn"
        @select="$emit('select', $event)"
        @edit="$emit('edit', $event)"
        @timeline="$emit('timeline', $event)"
        @restart="$emit('restart', $event)"
        @delete="$emit('delete', $event)"
      />
    </div>

    <!-- Issues under this mission (if expanded, has issues, and showIssues is on) -->
    <div v-if="expanded && missionIssues.length > 0" class="mission-issues">
      <div
        v-for="issue in missionIssues"
        :key="issue.id"
        class="issue-row cursor-pointer"
        :style="{ paddingLeft: ((depth + 1) * 16 + 8) + 'px' }"
        @click.stop="$router.push('/doc-net/issues/' + issue.id)"
      >
        <span class="issue-title">{{ issue.title }}</span>
        <q-space />
        <AssigneeChip
          v-if="issue.assignee_name"
          :name="issue.assignee_name"
          :type="issue.assignee_type === 'agent' ? 'agent' : 'human'"
          size="sm"
          class="q-mr-xs"
        />
        <StatusBadge :status="issue.status" size="sm" />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import type { DocNetMission, DocNetIssueSummary } from 'src/@types/docnet';
import { formatMissionSource } from 'src/utils/docnet/formatting';
import StatusBadge from '../../shared/StatusBadge.vue';
import AssigneeChip from '../../shared/AssigneeChip.vue';

const LEVEL_ICONS: Record<string, string> = {
  organization: 'corporate_fare',
  sub_organization: 'domain',
  team: 'groups',
  agent: 'smart_toy',
  task: 'task_alt',
  epic: 'rocket_launch',
  sprint: 'sprint',
  milestone: 'flag',
};

const LEVEL_COLORS: Record<string, string> = {
  organization: 'purple',
  sub_organization: 'deep-purple',
  team: 'indigo',
  agent: 'teal',
  task: 'blue-grey',
  epic: 'primary',
  sprint: 'cyan',
  milestone: 'amber-8',
};

export default defineComponent({
  name: 'MissionTreeItem',

  components: { StatusBadge, AssigneeChip },

  props: {
    mission: {
      type: Object as PropType<DocNetMission>,
      required: true,
    },
    childrenMap: {
      type: Object as PropType<Record<string, DocNetMission[]>>,
      required: true,
    },
    allMissions: {
      type: Array as PropType<DocNetMission[]>,
      required: true,
    },
    depth: {
      type: Number,
      default: 0,
    },
    progressFn: {
      type: Function as PropType<(id: string) => number>,
      required: true,
    },
  },

  emits: ['select', 'delete', 'edit', 'restart', 'timeline'],

  data() {
    return {
      expanded: this.depth < 2,
    };
  },

  computed: {
    children(): DocNetMission[] {
      return this.childrenMap[this.mission.id] || [];
    },

    hasChildren(): boolean {
      return this.children.length > 0;
    },

    missionIssues(): DocNetIssueSummary[] {
      return this.mission.issues || [];
    },

    isEmailMission(): boolean {
      // Legacy [Email] prefix was stripped from every row in the
      // DOCB-9880 data migration; ``source`` is the sole classifier.
      return this.mission.source === 'email';
    },

    orchestratorName(): string {
      // agents_used typically starts with the orchestrator name
      return this.mission.agents_used?.[0] ?? '';
    },

    /** Human-readable source label shown as a badge (e.g. "Email").
     *  Pass ``$t`` so the badge follows the active locale; falls
     *  back to the hardcoded English label when the
     *  ``source_<token>`` key isn't translated yet. */
    namePrefix(): string {
      return formatMissionSource(this.mission, (k: string) => this.$t(k));
    },

    /** Mission name as-is — the legacy "[Prefix]" was stripped from all
     * rows in the DOCB-9880 data migration, so ``mission.name`` is
     * already the clean display name.
     */
    displayName(): string {
      return this.mission.name ?? '';
    },

    levelIcon(): string {
      return LEVEL_ICONS[this.mission.level || ''] || 'rocket_launch';
    },

    levelColor(): string {
      return LEVEL_COLORS[this.mission.level || ''] || 'grey-7';
    },
  },
});
</script>

